package com.example.banking.repository;
import com.example.banking.entity.AppUser; import java.util.Optional; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param;
public interface UserRepository extends JpaRepository<AppUser,Long>{Optional<AppUser> findByEmail(String email); boolean existsByEmail(String email); @Query("select u from AppUser u where (:query is null or lower(u.email) like lower(concat('%', :query, '%')) or lower(u.fullName) like lower(concat('%', :query, '%')))") Page<AppUser> searchCustomers(@Param("query") String query,Pageable pageable);}
